INSERT INTO reviews (assignment_id,article_id,reviewer_id,recommendation,score,comments_to_author,comments_to_editor) SELECT ra.id, ra.article_id, ra.reviewer_id, 'MINOR_REVISION', 8, 'The manuscript is technically sound; please clarify the methodology and add recent references.', 'Recommend minor revision.' FROM review_assignments ra JOIN articles a ON a.id=ra.article_id WHERE a.doi='10.61413/GIPV6858' AND ra.reviewer_id=(SELECT id FROM users WHERE email='reviewer1@msj.aztu.edu.az') ON CONFLICT DO NOTHING;
